// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 32 (14.3% accuracy, 71.4% syntax):
//
// (1) 14/49 unterminated spans: The guidance contained FOUR explicit <<expr>>
//     examples which the model copied verbatim into backtick code blocks in its
//     reasoning (e.g., "`<<n*int(b...`"). When RenderedEndsWith(generated,"<<")
//     fired on these quoted examples, we entered constrained mode mid-reasoning
//     with a partial like "<<n*int(b" that the grammar could not complete.
//     Fix: Use ONE simple example in guidance (matching attempt 11's 100% syntax
//     formula), not four complex ones. Remove the "int()" elaborate examples.
//
// (2) 28/49 wrong answers: The minSpanTok=5 + CloseSpanIfComplete structure
//     (a) told the model "keep short" → truncated key factors, and
//     (b) closed at the FIRST complete parse prefix rather than the LONGEST.
//     Fix: Replace the constrained inner loop with CloseSpanWithinBudget which
//     internally tracks the LONGEST complete prefix within budget. This naturally
//     avoids premature closure and generates fuller expressions.
//
// (3) Phase 4 used exact token equality `next == "<<"` instead of RenderedEndsWith.
//     Fix: RenderedEndsWith throughout.
//
// Strategy: 5-phase open-then-reliably-close
//   Phase 1: UnconstrainedChunk batches until << detected (≤75% budget)
//   Phase 2: CloseSpanWithinBudget(remaining) — tracks longest complete expr
//   Phase 3: UnconstrainedStep until << or 90% budget (fallback free gen)
//   Phase 4: CloseSpanWithinBudget(remaining) — same close guarantee
//   Phase 5: Force OpenConstrainedSpan + CloseSpanWithinBudget(remaining)
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 1 (UnconstrainedChunk loop): insideConstrainedOut stays false until
//     stoppedOnOpen=true; then EnterObservedConstrainedSpan sets
//     currentConstrainedOut:=[] which is valid by precondition
//     parser.IsValidPrefix([]). Outside a span the implication is vacuously true.
//
//   Phase 2 (CloseSpanWithinBudget): library postcondition states
//     insideOut ==> parser.IsValidPrefix(currentOut). If it closes the span
//     (insideOut=false), the implication is vacuous and currentOut=[]. ✓
//
//   Phase 3 (UnconstrainedStep loop): insideConstrainedOut stays false until
//     RenderedEndsWith fires; then EnterObservedConstrainedSpan sets
//     currentConstrainedOut:=[] which is valid. Outside a span, vacuously true.
//
//   Phase 4 (CloseSpanWithinBudget): same library postcondition as Phase 2. ✓
//
//   Phase 5 (OpenConstrainedSpan): sets currentConstrainedOut:=[], valid by
//     precondition. Then CloseSpanWithinBudget preserves the invariant via its
//     library postcondition. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   Phase 1: UnconstrainedChunk postcondition gives |cg1| <= |old_generated| +
//     stepsUsed; steps grows by stepsUsed. EnterObservedConstrainedSpan leaves
//     generated unchanged and costs 0 steps. ✓
//
//   Phase 2: bud2 = maxSteps - steps, so after the call steps = maxSteps.
//     CloseSpanWithinBudget postcondition gives |wg2| <= |old_generated| + bud2,
//     so |generated| <= |generatedPrefix| + maxSteps = |generatedPrefix| + steps. ✓
//
//   Phase 3: UnconstrainedStep increments steps by 1; non-EOS appends at most
//     1 token; EOS appends nothing. EnterObservedConstrainedSpan adds 0. ✓
//
//   Phase 4: Same accounting as Phase 2 with bud4 = maxSteps - steps. ✓
//
//   Phase 5: OpenConstrainedSpan appends "<<" (1 token) and steps grows by 1.
//     CloseSpanWithinBudget: |generated| grows by at most bud5, steps by bud5. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve step by step. At the very end, write exactly: The answer is <<EXPR>> where EXPR is a complete arithmetic expression. Use only the variable names from the problem (without curly braces), numbers, and operators +, -, *, /, (, ), int(). The expression must include ALL variables needed to compute the final numeric answer - do not omit any factor. Use int() when a product of a quantity and a fraction should yield an integer. No LaTeX, no dollar signs, no braces in EXPR, no backslashes, no star-star. Example: The answer is <<n * price - discount>>");

var steps: nat := 0;
var hasCompletedSpan: bool := false;

var phase1Lim: nat := (maxSteps * 75) / 100;
if phase1Lim == 0 && maxSteps > 0 { phase1Lim := 1; }

var phase3Lim: nat := (maxSteps * 90) / 100;
if phase3Lim > maxSteps { phase3Lim := maxSteps; }
if phase3Lim < phase1Lim { phase3Lim := phase1Lim; }

// Phase 1: UnconstrainedChunk batches watching for "<<" (up to 75% budget)
while steps < phase1Lim && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Lim - steps
{
  var chunk: nat := 40;
  if steps + chunk > phase1Lim { chunk := phase1Lim - steps; }
  if chunk == 0 { break; }
  var cg1, soo1, soe1, su1 := helpers.UnconstrainedChunk(lm, prompt, generated, chunk, "<<", eosToken);
  generated := cg1;
  steps := steps + su1;
  if soe1 { break; }
  if soo1 {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2: If inside span, use ALL remaining budget — tracks longest complete expr
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var bud2: nat := maxSteps - steps;
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
  generated := wg2;
  insideConstrainedOut := wi2;
  currentConstrainedOut := wc2;
  steps := steps + bud2;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 3: Continue free generation step-by-step watching for "<<" (up to 90% budget)
while steps < phase3Lim && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase3Lim - steps
{
  var nxt3 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if nxt3 == eosToken { break; }
  generated := generated + [nxt3];
  if RenderedEndsWith(generated, "<<") {
    var eg3, ei3, ec3 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg3;
    insideConstrainedOut := ei3;
    currentConstrainedOut := ec3;
  }
}

// Phase 4: If inside span from Phase 3, use remaining budget to close
if insideConstrainedOut && !hasCompletedSpan && steps < maxSteps {
  var bud4: nat := maxSteps - steps;
  var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud4);
  generated := wg4;
  insideConstrainedOut := wi4;
  currentConstrainedOut := wc4;
  steps := steps + bud4;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 5: Force open a span if none completed, then close with remaining budget
if !hasCompletedSpan && !insideConstrainedOut && steps + 1 <= maxSteps {
  var fg5, fi5, fc5 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg5;
  insideConstrainedOut := fi5;
  currentConstrainedOut := fc5;
  steps := steps + 1;

  if insideConstrainedOut && steps < maxSteps {
    var bud5: nat := maxSteps - steps;
    var wg5, wi5, wc5 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud5);
    generated := wg5;
    insideConstrainedOut := wi5;
    currentConstrainedOut := wc5;
    steps := steps + bud5;
  }
}

